/* ── Sabbath grace (board #54) ───────────────────────────────────
   One missed day in any seven does not break a streak. People quit when a streak
   dies unfairly, and a week with a rest day in it is the rhythm this book teaches.
   The missed day is not counted — the streak carries on from where it was — and the
   grace renews seven days after the day it forgave. graceDay keeps that day's key,
   so the rule can be checked later instead of trusted.

   Pure on purpose: tools/test_dates.js runs it in five timezones. */
const GRACE_WINDOW = 7;
function streakAfter(streak, lastActive, graceDay, today){
  const last = normalizeKey(lastActive), s = Number(streak) || 0, g = normalizeKey(graceDay) || null;
  if (!last) return { streak: 1, graceDay: g, graced: false };
  const gap = dayDiff(last, today);
  if (gap === 0) return { streak: Math.max(s, 1), graceDay: g, graced: false };
  if (gap === 1) return { streak: s + 1, graceDay: g, graced: false };
  const missed = shiftKey(today, -1);
  if (gap === 2 && s > 0 && (!g || dayDiff(g, missed) >= GRACE_WINDOW))
    return { streak: s + 1, graceDay: missed, graced: true };
  return { streak: 1, graceDay: g, graced: false };
}
function graceReadyOn(graceDay){
  const g = normalizeKey(graceDay);
  return g ? shiftKey(g, GRACE_WINDOW) : "";
}

