/* ============ LESSON SEARCH ============
   Every day is already in memory (CURR), so search is a scan, not a request —
   it works offline. Results update in place so the input keeps focus. */
function searchLessons(q){
  q=String(q||"").trim().toLowerCase();if(q.length<2)return [];
  const terms=q.split(/\s+/).filter(Boolean),C=CURR(),out=[];
  for(let i=0;i<C.length&&out.length<40;i++){const o=C[i];
    const head=[o.t,o.r,o.wt,o.p,o.s].join(" ").toLowerCase();
    const body=[o.ml,o.wl,o.mu,o.wu,o.x].join(" ").toLowerCase();
    if(!terms.every(t=>head.includes(t)||body.includes(t)))continue;
    const tt=String(o.t||"").toLowerCase(),rr=String(o.r||"").toLowerCase();
    out.push({g:i+1,o,score:terms.reduce((n,t)=>n+(tt.includes(t)?3:0)+(rr.includes(t)?2:0)+(head.includes(t)?1:0),0)});}
  return out.sort((a,b)=>b.score-a.score||a.g-b.g);
}
function renderSearchResults(q){
  const box=document.getElementById("lesson-search-results");if(!box)return;
  if(String(q||"").trim().length<2){box.innerHTML="";return;}
  const r=searchLessons(q);
  box.innerHTML=r.length?`<p class="faint" style="font-size:12px;margin:0 0 6px">${r.length}${r.length===40?"+":""} lesson${r.length===1?"":"s"}</p>`+
    r.map(({g,o})=>`<button class="list-item" data-act="open-lesson" data-id="${g}">
      <div class="av">${S.done["day"+g]?"✅":pillarEmoji(o.p)}</div>
      <div class="tx"><b>${esc(o.t||("Day "+g))}</b><small>${esc(o.r||"")} · Yr ${o.y} · Day ${g}</small></div>
      <span style="font-size:16px">›</span></button>`).join("")
    :`<p class="muted" style="font-size:13px">No lessons match “${esc(q)}”.</p>`;
}
document.addEventListener("input", ev => {
  if (ev.target && ev.target.id === "lesson-search") renderSearchResults(ev.target.value);
});
