/* ---- MEMORY MATCH ---- */
let MM={};
function memoryStart(){
  const pairs=DATA.games.memory.slice(0,6);
  let cards=[];pairs.forEach((p,i)=>{cards.push({pid:i,type:"ref",t:p.ref});cards.push({pid:i,type:"txt",t:p.text});});
  for(let i=cards.length-1;i>0;i--){const j=Math.random()*(i+1)|0;[cards[i],cards[j]]=[cards[j],cards[i]];}
  MM={cards,flip:[],matched:0,moves:0};memoryRender();
}
function memoryRender(){
  gset(`<div class="row between"><span class="eyebrow">Verse Memory</span><span class="pill">${MM.moves} moves · ${MM.matched}/6</span></div>
    <p class="faint" style="font-size:12px;margin:6px 0 12px">Match each reference to its verse.</p>
    <div class="mem-grid">${MM.cards.map((c,i)=>{
      const open=MM.flip.includes(i)||c.done;
      return `<div class="mem-card ${open?"flip":""} ${c.done?"done":""}" data-act="mem-flip" data-i="${i}">${open?esc(c.t):"✦"}</div>`;}).join("")}</div>`);
}
function memFlip(i){
  const c=MM.cards[i];if(c.done||MM.flip.includes(i)||MM.flip.length>=2)return;
  MM.flip.push(i);memoryRender();
  if(MM.flip.length===2){MM.moves++;
    const[a,b]=MM.flip.map(x=>MM.cards[x]);
    if(a.pid===b.pid&&a.type!==b.type){a.done=b.done=true;MM.matched++;MM.flip=[];
      setTimeout(()=>{memoryRender();if(MM.matched===6)memoryEnd();},350);}
    else{setTimeout(()=>{MM.flip=[];memoryRender();},900);}
  }
}
function memoryEnd(){
  const xp=Math.max(20,80-MM.moves*4);addXP(xp,"Memory match");S.gameWins++;earn("gamer");save();
  gset(`<div class="center" style="padding:16px 0"><div style="font-size:48px">🧩</div>
    <h3 class="serif" style="font-size:23px">Matched!</h3><p class="muted">${MM.moves} moves · +${xp} XP</p>
    <button class="btn primary block" style="margin-top:14px" data-act="memory-start">Play again</button>
    <button class="btn ghost block" style="margin-top:9px" data-act="close-render">Done</button></div>`);
}

